{# ── Field remap, WO-per-run schema (2026-09) ─────────────────────────────
   This format still read the pre-rewrite IB Work Order shape
   (item_code/stage/target_qty/target_uom/pcs_to_make/logs_to_make/
   jumbo_roll) - all replaced back on this branch by the "Work Order = one
   run" model (source_item/source_qty/source_batch/current_stage + a real
   outputs child table, since one run can now produce more than one item).
   Real live WOs were printing "Item Code: None" / "Stage: None" until this
   fix - flagged separately from the print-theme restyle, fixed here. #}
{% set machine_name = frappe.db.get_value("IB Machine", doc.machine, "machine_name") if doc.machine else None %}
{% set src_batch = frappe.get_doc("IB Batch", doc.source_batch) if doc.source_batch else None %}
{# Per-output dims (color/qty_pkg/total_pkg only - width/length/gsm already
   live on the output row itself) resolved via the row-exact
   `sales_order_item` link each output carries (items 119/123's own fix for
   item-code-ambiguity on a multi-line Sales Order) - never the SO name or
   customer, which must never appear on this floor-worker document
   (CLAUDE.md item 119). #}
{% set ns = namespace(so_dims={}) %}
{% for o in doc.outputs %}
  {% if o.sales_order_item and o.sales_order_item not in ns.so_dims %}
    {% set _ = ns.so_dims.update({o.sales_order_item: frappe.db.get_value("Sales Order Item", o.sales_order_item, ["color", "qty_pkg", "total_pkg"], as_dict=True)}) %}
  {% endif %}
{% endfor %}
<style>
  @font-face {
    font-family: "Inter";
    src: url("/assets/instabiz/fonts/InterVariable.woff2") format("woff2");
    font-weight: 100 900;
    font-style: normal;
  }
  body { font-family: "Inter", Arial, sans-serif; font-size: 12px; color: #111; padding: 10px; }
  .print-format { margin-top: 0mm; margin-right: 0mm; margin-bottom: 0mm; margin-left: 0mm; }
  /* Negative side-margins matching body's own padding so the letterhead image
     bleeds truly edge-to-edge (100% of the page) instead of 100% of the
     10px-inset content area it would otherwise be constrained to. */
  .jo-header { text-align: center; margin: 0 -10px 0; }
  .jo-header img { width: 100%; max-height: 60px; object-fit: contain; display: block; margin: 0 auto; }

  {# ── IB Print Theme title bar (see ib_packing_list.html reference) ──
     Bleeds edge-to-edge same as the letterhead above it (negative side
     margins matching body's own 10px padding). #}
  .ib-title-bar {
    background: #fdf3ee; border-bottom: 2px solid #d97757;
    text-align: center; padding: 6px; margin: 0 -10px 14px;
  }
  .ib-title-bar .t { font-size: 18px; font-weight: bold; letter-spacing: 1px; color: #b9502f; }
  .ib-title-bar .s { font-size: 10px; color: #666; margin-top: 2px; }

  table.jo-meta { width: 100%; table-layout: fixed; border-collapse: separate; border-spacing: 0; margin-bottom: 14px; }
  table.jo-meta td { padding: 5px 8px; vertical-align: top; border: none; border-bottom: 1px solid #eee; background: none; }
  table.jo-meta td.label { font-weight: bold; color: #444; }
  table.jo-meta td.value { }
  table.jo-meta col.jo-label-col { width: 160px; }
  table.jo-meta col.jo-value-col { width: auto; }
  .jo-section-title { font-weight: bold; font-size: 12px; text-transform: uppercase; color: #b9502f;
                       border-bottom: 1px solid #d97757; margin: 16px 0 6px; padding-bottom: 2px; }
  .jo-output { border: 1px solid #eee; border-radius: 4px; margin: 0 0 12px; padding: 10px 12px; }
  .jo-output + .jo-output { margin-top: 10px; }
  .jo-output-title { font-weight: bold; font-size: 13px; margin-bottom: 4px; }
  .jo-qty-block { text-align: center; margin: 10px 0; }
  .jo-qty-block .jo-qty-val { font-size: 26px; font-weight: bold; }
  .jo-qty-block .jo-qty-uom { font-size: 14px; color: #555; }
  .jo-footer { margin-top: 30px; width: 100%; }
  .jo-footer td { padding: 4px; }
  .sig-line { border-top: 1px solid #444; padding-top: 4px; text-align: center; font-size: 10px; color: #555; }
</style>

<div class="jo-header">
  <img src="/files/Instabiz_LH_v2.png">
</div>

<div class="ib-title-bar">
  <div class="t">JOB ORDER</div>
  <div class="s">WO No: <strong>{{ doc.name }}</strong></div>
</div>

<table class="jo-meta">
  {# Sales Order / customer are intentionally never shown on this format —
     it is a floor-worker document (CLAUDE.md item 119). #}
  <tr><td class="label">Stage</td><td class="value">{{ doc.current_stage or "" }}</td></tr>
  {% if doc.machine %}
  <tr><td class="label">Machine</td><td class="value">{{ doc.machine }}{% if machine_name %} — {{ machine_name }}{% endif %}</td></tr>
  {% endif %}
  {% if doc.priority %}
  <tr><td class="label">Priority</td><td class="value">{{ doc.priority }}</td></tr>
  {% endif %}
</table>

{# ── Source (input) batch — replaces the old, no-longer-existent Jumbo
   Roll link. IB Batch is the current RM/FG genealogy record (item 161). #}
{% if src_batch %}
<div class="jo-section-title">Source Batch</div>
<table class="jo-meta">
  <tr><td class="label">Batch</td><td class="value">{{ src_batch.name }}</td></tr>
  <tr><td class="label">Item</td><td class="value">{{ doc.source_item }}</td></tr>
  {% if doc.source_qty %}
  <tr><td class="label">Qty Issued</td><td class="value">{{ doc.source_qty }}</td></tr>
  {% endif %}
  {% if src_batch.width_mm %}
  <tr><td class="label">Width (MM)</td><td class="value">{{ src_batch.width_mm }}</td></tr>
  {% endif %}
  {% if src_batch.gsm %}
  <tr><td class="label">GSM</td><td class="value">{{ src_batch.gsm }}</td></tr>
  {% endif %}
</table>
{% endif %}

{# ── Outputs — a run can produce more than one item now. One block per
   output, each with its own qty/dims/packing details. #}
<div class="jo-section-title">{{ "Outputs" if doc.outputs|length > 1 else "Output" }}</div>
{% for o in doc.outputs %}
{% set dims = ns.so_dims.get(o.sales_order_item) %}
<div class="jo-output">
  <div class="jo-output-title">{{ o.item_code }}{% if o.item_name %} — {{ o.item_name }}{% endif %}</div>

  <div class="jo-qty-block">
    <div class="jo-qty-val">{{ o.planned_qty or 0 }}</div>
    <div class="jo-qty-uom">{{ o.uom or "" }}</div>
  </div>

  {% if dims and (dims.color or dims.qty_pkg or dims.total_pkg) or o.width_mm or o.length_mtr or o.gsm %}
  <table class="jo-meta">
    {% if o.width_mm %}
    <tr><td class="label">Width (MM)</td><td class="value">{{ o.width_mm }}</td></tr>
    {% endif %}
    {% if o.length_mtr %}
    <tr><td class="label">Length (MTR)</td><td class="value">{{ o.length_mtr }}</td></tr>
    {% endif %}
    {% if o.gsm %}
    <tr><td class="label">GSM</td><td class="value">{{ o.gsm }}</td></tr>
    {% endif %}
    {% if dims and dims.color %}
    <tr><td class="label">Color</td><td class="value">{{ dims.color }}</td></tr>
    {% endif %}
    {% if dims and dims.qty_pkg %}
    <tr><td class="label">Qty/Pkg</td><td class="value">{{ dims.qty_pkg }}</td></tr>
    {% endif %}
    {% if dims and dims.total_pkg %}
    <tr><td class="label">Total Pkg</td><td class="value">{{ dims.total_pkg }}</td></tr>
    {% endif %}
  </table>
  {% endif %}

  {% if o.brand or o.core or o.ctn or o.shrink_film or o.packing_type or o.pack_count %}
  <table class="jo-meta">
    {% if o.packing_type %}
    <tr><td class="label">Packing Type</td><td class="value">{{ o.packing_type }}</td></tr>
    {% endif %}
    {% if o.brand %}
    <tr><td class="label">Brand</td><td class="value">{{ o.brand }}</td></tr>
    {% endif %}
    {% if o.core %}
    <tr><td class="label">Core</td><td class="value">{{ o.core }}</td></tr>
    {% endif %}
    {% if o.ctn %}
    <tr><td class="label">CTN</td><td class="value">{{ o.ctn }}</td></tr>
    {% endif %}
    {% if o.shrink_film %}
    <tr><td class="label">Shrink Film</td><td class="value">{{ o.shrink_film }}</td></tr>
    {% endif %}
    {% if o.pack_count %}
    <tr><td class="label">No. of Logs/Pcs</td><td class="value">{{ o.pack_count }}</td></tr>
    {% endif %}
  </table>
  {% endif %}
</div>
{% endfor %}

{% if doc.notes %}
<div class="jo-section-title">Notes</div>
<div>{{ doc.notes }}</div>
{% endif %}

<table class="jo-footer">
  <tr>
    <td style="width:33%"><div class="sig-line">Operator Signature</div></td>
    <td style="width:33%"><div class="sig-line">Actual Output Qty / Date</div></td>
    <td style="width:33%"><div class="sig-line">Checked By</div></td>
  </tr>
</table>
